export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    
    // Serve static assets (CSS, JS, images) - note: HTML uses /assets/ prefix
    if (url.pathname.startsWith('/assets/') || url.pathname.startsWith('/css/') || url.pathname.startsWith('/js/') || url.pathname.startsWith('/img/')) {
      if (env.ASSETS) {
        return env.ASSETS.fetch(request);
      }
      return new Response('Not Found', { status: 404 });
    }

    // Route pages
    const routes = {
      '/': '/',
      '/home': '/',
      '/about': '/about',
      '/services': '/services',
      '/contact-me': '/contact-me',
      '/contact': '/contact-me',
      '/cv': '/cv',
      '/pronouns': '/pronouns',
      '/login': '/login',
      '/referral-programs': '/referral-programs',
      '/referral': '/referral-programs',
      '/self-service': '/self-service',
      '/n8n': '/n8n',
      '/zapier-to-n8n': '/zapier-to-n8n',
      '/make-to-n8n': '/make-to-n8n',
      '/switch-to-n8n': '/switch-to-n8n',
      '/switch-to-mautic': '/switch-to-mautic',
      '/proxmox': '/proxmox',
      '/proxmox-virtualization': '/proxmox-virtualization',
      '/3-2-1-1-0-backup-strategy': '/3-2-1-1-0-backup-strategy',
      '/activecampaign': '/activecampaign',
      '/clickfunnels': '/clickfunnels',
      '/gohighlevel': '/gohighlevel',
      '/keap': '/keap',
      '/oncehub': '/oncehub',
      '/posthog': '/posthog',
      '/kb-support': '/kb-support',
    };

    const pageKey = routes[url.pathname];
    const html = PAGES[pageKey];

    if (html) {
      return new Response(html, {
        headers: { 'Content-Type': 'text/html' },
      });
    }

    // 404
    return new Response(PAGES['/'].replace(/<title>[^<]+<\/title>/, '<title>404 - Not Found</title>').replace(/<h1[^>]*>[^<]+<\/h1>/, '<h1>404 - Page Not Found</h1>'), {
        headers: { 'Content-Type': 'text/html' },
        status: 404
    });
  },
};